  public const MAX_LIMIT = 9007199254740991;

  public const DEFAULTS = [
    'tools' => ['pages_enabled' => FALSE, 'disabled' => []],
    'mcp' => ['product_documents' => ['enabled' => FALSE, 'content_types' => []]],
    'task_limits' => ['max_model_calls' => 40, 'max_tokens' => 200000],
  ];

  /** Generated by the Node application: npm run sync:harness-catalog. */
  public const TOOL_GROUPS = [
    'web_search' => ['label' => '联网搜索（DeepSeek）', 'tools' => [
      'web_search' => '搜索公开网页',
      'web_fetch' => '抓取公开网页正文',
    ]],
    'utility' => ['label' => '通用查询', 'tools' => [
      'query_time_date' => '日期与时间',
      'get_weather' => '天气查询',
    ]],
    'cms' => ['label' => '内容查询', 'tools' => [
      'get_content' => '站点内容',
      'get_node_type' => '内容类型',
      'get_conversations' => '对话记录',
      'get_sessions' => '会话记录',
      'get_components' => '组件目录与模板',
      'get_landing_page' => '页面列表',
      'get_users_statistics' => '用户统计',
    ]],
    'design' => ['label' => '设计辅助', 'tools' => [
      'get_assets' => '设计素材',
      'get_design_system' => '设计系统建议',
      'analyze_image' => '图片理解',
    ]],
    'pages' => ['label' => '页面草稿', 'tools' => [
      'create_page' => '创建草稿',
      'get_page' => '读取本人草稿',
      'apply_widget' => '追加组件',
      'delete_page' => '删除本人草稿',
    ]],
    'product_documents' => ['label' => '产品资料（MCP）', 'tools' => [
      'search_product_documents' => '搜索产品资料',
      'get_product_document' => '读取产品资料正文',
    ]],
    'analytics' => ['label' => '数量统计（可选）', 'tools' => [
      'list_analytics_datasets' => '可用统计数据集',
      'count_analytics_entities' => '查询内容数量',
    ]],
    'entities' => ['label' => '实体内容（可选）', 'tools' => [
      'list_resources' => '发现内容资源',
      'describe_resource' => '读取资源结构',
      'query_entities' => '查询实体',
      'read_entity' => '读取实体字段',
      'validate_entity' => '校验实体字段',
      'create_entity_draft' => '创建实体草稿',
      'update_entity' => '更新实体草稿修订',
    ]],
    'office_word' => ['label' => 'Word 文档（可选）', 'tools' => [
      'create_word_document' => '创建 Word 文档',
      'update_word_document' => '修改 Word 文档',
    ]],
    'office_resources' => ['label' => '办公文档读取（可选）', 'tools' => [
      'list_office_documents' => '当前会话的办公文档',
      'read_office_document' => '读取办公文档选区',
      'read_spreadsheet' => '读取工作表选区',
    ]],
    'office_sheet' => ['label' => 'Excel 工作簿（可选）', 'tools' => [
      'create_spreadsheet' => '创建 Excel 工作簿',
      'update_spreadsheet' => '修改 Excel 工作簿',
    ]],
  ];

  public static function toolNames(): array {
    return array_keys(array_merge(...array_column(self::TOOL_GROUPS, 'tools')));
  }

  /** Missing settings on existing sites behave like a new installation. */
  public static function normalize(mixed $value): array {
    $result = self::DEFAULTS;
    if (!is_array($value)) {
      return $result;
    }
    $tools = $value['tools'] ?? NULL;
    if (is_array($tools) && is_bool($tools['pages_enabled'] ?? NULL)) {
      $result['tools']['pages_enabled'] = $tools['pages_enabled'];
    }
    if (is_array($tools) && is_array($tools['disabled'] ?? NULL)) {
      $result['tools']['disabled'] = array_values(array_intersect(self::toolNames(),
        array_filter($tools['disabled'], 'is_string')));
    }
    $documents = is_array($value['mcp'] ?? NULL) ? ($value['mcp']['product_documents'] ?? NULL) : NULL;
    if (is_array($documents)) {
      $result['mcp']['product_documents']['enabled'] = ($documents['enabled'] ?? FALSE) === TRUE;
      if (is_array($documents['content_types'] ?? NULL)) {
        $result['mcp']['product_documents']['content_types'] = array_values(array_unique(array_filter(
          $documents['content_types'], static fn($type) => is_string($type) && preg_match('/^[a-z][a-z0-9_]{0,31}$/', $type))));
      }
    }
    $limits = $value['task_limits'] ?? NULL;
    if (is_array($limits)) {
      foreach ($result['task_limits'] as $key => $default) {
        $limit = $limits[$key] ?? NULL;
        if (is_int($limit) && $limit > 0 && $limit <= self::MAX_LIMIT) {
          $result['task_limits'][$key] = $limit;
        }
      }
    }
    return $result;
  }

}
